/**
 * Unified Cross-Country Panel Dataset
 *
 * One row per country-year, combining income, health, spending, and demographic
 * indicators from World Bank, IMF, WHO, OECD, and Eurostat.
 *
 * Designed for the Optimitron optimizer to identify optimal budgets and policies
 * that maximize median income and healthy life expectancy.
 *
 * Generated by: scripts/generate-country-panel.ts
 * Refresh with: pnpm --filter @optimitron/data run generate:country-panel
 */

import {
  COUNTRY_PANEL_DATA as GENERATED_COUNTRY_PANEL_DATA,
  COUNTRY_PANEL_METADATA as GENERATED_COUNTRY_PANEL_METADATA,
} from '../generated/country-panel';

export interface CountryPanelRow {
  /** ISO 3166-1 alpha-3 country code */
  jurisdictionIso3: string;
  /** Human-readable country name */
  jurisdictionName: string;
  /** Calendar year */
  year: number;

  // === TARGET METRICS ===

  /** After-tax median income per capita, PPP (best available source) */
  afterTaxMedianIncomePerCapitaPpp: number | null;
  /** Source of the after-tax median income value */
  afterTaxMedianIncomeSource: string | null;
  /** Whether the income value is from a survey or derived */
  afterTaxMedianIncomeIsAfterTax: boolean;
  /** Pre-tax median income per capita, PPP (World Bank PIP) */
  medianIncomePerCapitaPpp: number | null;
  /** GDP per capita, PPP current international $ (World Bank) */
  gdpPerCapitaPpp: number | null;

  /** Healthy life expectancy at birth, years (WHO HALE) */
  haleYears: number | null;
  /** Life expectancy at birth, total years (World Bank) */
  lifeExpectancyYears: number | null;
  /** Infant mortality per 1,000 live births (World Bank) */
  infantMortalityPer1000: number | null;

  // === GOVERNMENT SPENDING (predictors) — % of GDP ===

  /** General government total expenditure, all levels (IMF Fiscal Monitor) */
  totalGovSpendingPctGdp: number | null;
  /** Current health expenditure (World Bank) */
  healthSpendingPctGdp: number | null;
  /** Government education expenditure (World Bank) */
  educationSpendingPctGdp: number | null;
  /** Military expenditure (World Bank) */
  militarySpendingPctGdp: number | null;
  /** R&D expenditure (World Bank) */
  rdSpendingPctGdp: number | null;

  // === GOVERNMENT SPENDING — per capita PPP (derived) ===

  /** Total gov spending per capita PPP (totalGovSpendingPctGdp × gdpPerCapitaPpp / 100) */
  totalGovSpendingPerCapitaPpp: number | null;
  /** Health spending per capita PPP */
  healthSpendingPerCapitaPpp: number | null;
  /** Education spending per capita PPP */
  educationSpendingPerCapitaPpp: number | null;
  /** Military spending per capita PPP */
  militarySpendingPerCapitaPpp: number | null;
  /** R&D spending per capita PPP */
  rdSpendingPerCapitaPpp: number | null;

  // === INEQUALITY & WELFARE ===

  /** Gini index (0 = equal, 100 = max inequality) */
  giniIndex: number | null;
  /** Poverty rate at $2.15/day (2017 PPP) */
  povertyRate: number | null;

  // === DEMOGRAPHICS ===

  /** Total population */
  population: number | null;
}

export interface CountryPanelMetadata {
  generatedAt: string;
  rowCount: number;
  countryCount: number;
  yearRange: [number, number];
  sources: string[];
}

export const COUNTRY_PANEL: CountryPanelRow[] = GENERATED_COUNTRY_PANEL_DATA;
export const COUNTRY_PANEL_METADATA: CountryPanelMetadata =
  GENERATED_COUNTRY_PANEL_METADATA;

/** Get all rows */
export function getCountryPanel(): CountryPanelRow[] {
  return COUNTRY_PANEL;
}

/** Get rows for a specific country */
export function getCountryPanelByCountry(
  iso3: string,
): CountryPanelRow[] {
  return COUNTRY_PANEL.filter((r) => r.jurisdictionIso3 === iso3);
}

/**
 * Get one row per country where every field is filled in from the most
 * recent year in which it was non-null. Handles the common case where IMF
 * forecast rows (2025–2026) only ship `totalGovSpendingPctGdp` and would
 * otherwise wipe out all the other fields on the "latest" row.
 *
 * Performance: O(rows). Walks the full panel once, tracking the max-year
 * non-null per field per country. `jurisdictionIso3` / `jurisdictionName` /
 * `year` are taken from the most recent row that had any observed field.
 */
export function getCountryPanelLatestResolved(): CountryPanelRow[] {
  // Keys we want coalesced — every CountryPanelRow field except the
  // identifier/timestamp trio.
  const FIELDS = [
    "afterTaxMedianIncomePerCapitaPpp",
    "afterTaxMedianIncomeSource",
    "afterTaxMedianIncomeIsAfterTax",
    "medianIncomePerCapitaPpp",
    "gdpPerCapitaPpp",
    "haleYears",
    "lifeExpectancyYears",
    "infantMortalityPer1000",
    "totalGovSpendingPctGdp",
    "healthSpendingPctGdp",
    "educationSpendingPctGdp",
    "militarySpendingPctGdp",
    "rdSpendingPctGdp",
    "totalGovSpendingPerCapitaPpp",
    "healthSpendingPerCapitaPpp",
    "educationSpendingPerCapitaPpp",
    "militarySpendingPerCapitaPpp",
    "rdSpendingPerCapitaPpp",
    "giniIndex",
    "povertyRate",
    "population",
  ] as const satisfies ReadonlyArray<keyof CountryPanelRow>;

  interface Accumulator {
    row: CountryPanelRow;
    fieldYears: Partial<Record<(typeof FIELDS)[number], number>>;
  }

  const byIso3 = new Map<string, Accumulator>();

  for (const row of COUNTRY_PANEL) {
    let acc = byIso3.get(row.jurisdictionIso3);
    if (!acc) {
      acc = {
        fieldYears: {},
        row: {
          ...row,
          // Reset every coalesced field; we'll refill from this same row below.
          ...Object.fromEntries(FIELDS.map((key) => [key, null])) as Partial<CountryPanelRow>,
        } as CountryPanelRow,
      };
      byIso3.set(row.jurisdictionIso3, acc);
    }

    // Name/year metadata: track the latest row we've seen for this country.
    if (row.year >= acc.row.year) {
      acc.row.year = row.year;
      acc.row.jurisdictionName = row.jurisdictionName;
    }

    for (const field of FIELDS) {
      const value = row[field];
      // `afterTaxMedianIncomeIsAfterTax` is a boolean — always considered
      // defined, so take the most recent observation unconditionally.
      if (field === "afterTaxMedianIncomeIsAfterTax") {
        const prior = acc.fieldYears[field] ?? -Infinity;
        if (row.year >= prior) {
          acc.row[field] = value as boolean;
          acc.fieldYears[field] = row.year;
        }
        continue;
      }
      if (value === null) continue;
      const prior = acc.fieldYears[field] ?? -Infinity;
      if (row.year >= prior) {
        (acc.row[field] as typeof value) = value;
        acc.fieldYears[field] = row.year;
      }
    }
  }

  return [...byIso3.values()]
    .map((acc) => acc.row)
    .sort((a, b) => a.jurisdictionIso3.localeCompare(b.jurisdictionIso3));
}

/** Get rows for a specific year */
export function getCountryPanelByYear(year: number): CountryPanelRow[] {
  return COUNTRY_PANEL.filter((r) => r.year === year);
}
